/**
 * OGame Infinity 0.84 — settings page and settings form wiring.
 *
 * The game's own Options page (`page=options`) is the natural place for the
 * extension's settings: the panel is injected at the top of the content area in
 * the same old-design markup as the analyzer, and the very same form is available
 * as the "Settings" tab of the analyzer panel.
 *
 * The form is generated by lib/panel.js (`settingsSection` / `settingsPanel`); the
 * wiring lives here, in one place, so both entry points behave identically.
 */
(function (root) {
    'use strict';

    const OGI = root.OGI || {};

    /**
     * Read the form values.
     *
     * @param {Element} container Form container.
     * @returns {object} Settings patch.
     */
    function readForm(container) {
        const patch = {};
        const rate = [null, null, null];
        const fields = container.querySelectorAll('[data-ogi-setting]');
        for (let i = 0; i < fields.length; i++) {
            const field = fields[i];
            const key = field.getAttribute('data-ogi-setting');
            if (key === 'tradeRate') {
                const index = parseInt(field.getAttribute('data-ogi-rate'), 10);
                if (index >= 0 && index <= 2) rate[index] = field.value;
                continue;
            }
            patch[key] = field.type === 'checkbox' ? field.checked : field.value;
        }
        if (rate[0] !== null) patch.tradeRate = rate;
        return patch;
    }

    /**
     * Wire the settings controls of a container.
     *
     * @param {Element} container Container holding the settings panel.
     * @param {object} ctx Extension context.
     * @param {function(string=)=} refresh Called after a change with a status text.
     */
    OGI.wireSettingsForm = function (container, ctx, refresh) {
        const i18n = ctx.i18n;
        const store = ctx.store;

        function rerender(status) {
            if (typeof refresh === 'function') refresh(status);
        }

        function save(status) {
            OGI.write(store, readForm(container));
            rerender(status || i18n('SET_SAVED'));
        }

        const inputs = container.querySelectorAll('[data-ogi-setting]');
        for (let i = 0; i < inputs.length; i++) {
            // Checkboxes and selects apply immediately, numbers on "Save"; both
            // paths go through the same validation.
            inputs[i].addEventListener('change', function () {
                if (this.type === 'checkbox' || this.tagName === 'SELECT') save();
            });
        }

        const actions = container.querySelectorAll('[data-ogi-action]');
        for (let i = 0; i < actions.length; i++) {
            actions[i].addEventListener('click', function (event) {
                event.preventDefault();
                const action = this.getAttribute('data-ogi-action');
                if (action === 'save') {
                    save();
                } else if (action === 'reset') {
                    OGI.reset(store);
                    rerender(i18n('SET_SAVED'));
                } else if (action === 'export') {
                    // The exported document replaces the form so it can be copied.
                    const settings = OGI.read(store);
                    container.innerHTML = OGI.settingsPanel(store.data(), { i18n: i18n }) +
                        '<textarea class="ogi-export" rows="12" spellcheck="false">' +
                        OGI.esc(OGI.exportJson(settings) + '\n\n' + JSON.stringify({
                            spies: store.data().spies.length,
                            combats: store.data().combats.length,
                            planets: Object.keys(store.data().planets || {}).length,
                        }, null, 1)) +
                        '</textarea>' +
                        '<div class="ogi-note">' + OGI.esc(i18n('SET_IMPORT_HINT')) + '</div>' +
                        '<textarea class="ogi-import" rows="6" spellcheck="false"></textarea>' +
                        '<button type="button" data-ogi-action="import">' + OGI.esc(i18n('SET_IMPORT')) + '</button>';
                    OGI.wireSettingsForm(container, ctx, refresh);
                } else if (action === 'import') {
                    const field = container.querySelector('.ogi-import');
                    const parsed = OGI.importJson(field ? field.value : '');
                    if (!parsed) {
                        rerender(i18n('SET_BAD_IMPORT'));
                        return;
                    }
                    OGI.write(store, parsed);
                    rerender(i18n('SET_SAVED'));
                }
            });
        }
    };

    /**
     * Render and wire the settings panel inside a container.
     *
     * @param {Element} container Container.
     * @param {object} ctx Extension context.
     * @param {object} [options] Options: status.
     */
    OGI.mountSettingsPanel = function (container, ctx, options) {
        const opt = options || {};
        const status = { text: opt.status || '' };

        function render() {
            container.innerHTML = OGI.settingsPanel(ctx.store.data(), {
                i18n: ctx.i18n,
                status: status.text,
            }) + '<div class="ogi-status" data-ogi-status></div>' +
                '<button type="button" data-ogi-action="save">' + OGI.esc(ctx.i18n('SET_SAVE')) + '</button>';
            const line = container.querySelector('[data-ogi-status]');
            if (line && status.text) line.textContent = status.text;
            const saveButton = container.querySelector('[data-ogi-action="save"]');
            if (saveButton) {
                saveButton.addEventListener('click', function () {
                    OGI.write(ctx.store, readForm(container));
                    status.text = ctx.i18n('SET_SAVED');
                    render();
                });
            }
            OGI.wireSettingsForm(container, ctx, function (text) {
                status.text = text || '';
                render();
            });
        }

        render();
    };

    /**
     * Handle the game's Options page: inject the settings panel at the top of the
     * content area.
     *
     * @param {object} ctx Extension context.
     */
    OGI.mountOptions = function (ctx) {
        const content = document.getElementById('content') || document.body;
        const host = OGI.mountHost(content, 'ogi-options-host');
        OGI.mountSettingsPanel(host, ctx);
    };
})(typeof globalThis !== 'undefined' ? globalThis : this);
